[patterns/application/api-microservices/PTN-APP-API-030-message-queue-pattern.md#variation-1-work-queue-load-distribution]

#### Variation 1: Work Queue (Load Distribution)

**Scenario**: Distribute work across multiple consumer instances for parallel processing

**Implementation**:

```csharp
// Producer: Publish tasks to work queue
public class ClaimProcessingProducer
{
    private readonly IBus _bus;

    public async Task SubmitClaimForProcessingAsync(Claim claim)
    {
        await _bus.Publish(new ProcessClaimCommand
        {
            ClaimId = claim.Id,
            MemberId = claim.MemberId,
            ProviderId = claim.ProviderId,
            ServiceDate = claim.ServiceDate,
            LineItems = claim.LineItems
        });

        _logger.LogInformation("Claim {ClaimId} submitted for processing", claim.Id);
    }
}

// Multiple consumers compete for messages
public class ClaimProcessingConsumer : IConsumer<ProcessClaimCommand>
{
    public async Task Consume(ConsumeContext<ProcessClaimCommand> context)
    {
        var command = context.Message;

        _logger.LogInformation("Consumer {Instance} processing claim {ClaimId}",
            Environment.MachineName, command.ClaimId);

        try
        {
            // Perform claim adjudication
            var result = await _adjudicationEngine.ProcessAsync(command);

            // Save result
            await _claimRepository.SaveAsync(result);

            // Publish completion event
            await context.Publish(new ClaimProcessedEvent
            {
                ClaimId = command.ClaimId,
                Result = result
            });

            // ACK message - successfully processed
        }
        catch (TransientException ex)
        {
            // Temporary failure - requeue for retry
            _logger.LogWarning("Transient failure processing claim {ClaimId}: {Error}",
                command.ClaimId, ex.Message);
            throw; // Framework will requeue
        }
        catch (PermanentException ex)
        {
            // Invalid data - move to DLQ
            _logger.LogError("Permanent failure processing claim {ClaimId}: {Error}",
                command.ClaimId, ex.Message);

            await context.Send(new MoveToDeadLetterCommand
            {
                OriginalMessage = context.Message,
                Reason = ex.Message
            });
        }
    }
}
```

**Configuration** (RabbitMQ):
```json
{
  "QueueName": "claims.processing",
  "Durable": true,
  "AutoDelete": false,
  "PrefetchCount": 10,
  "ConsumerInstances": 5,
  "MaxRetries": 3,
  "RetryDelay": "00:00:30"
}
```

**Benefits**: Horizontal scaling by adding consumers; automatic load distribution; isolated failures (one consumer crash doesn't impact others)

