#### Variation 2: Priority Queue

**Scenario**: Process high-priority messages (STAT orders, emergency authorizations) before standard messages

**Implementation**:

```csharp
// Producer sets message priority
public async Task SubmitPriorAuthRequestAsync(PriorAuthRequest request)
{
    var priority = request.IsUrgent ? 10 : 5; // 0-10 scale

    await _bus.Publish(new ProcessPriorAuthCommand
    {
        RequestId = request.Id,
        MemberId = request.MemberId,
        ServiceCode = request.ServiceCode,
        IsUrgent = request.IsUrgent
    }, ctx =>
    {
        ctx.Priority = (byte)priority;
        ctx.TimeToLive = request.IsUrgent
            ? TimeSpan.FromHours(4)
            : TimeSpan.FromDays(2);
    });
}

// Consumer processes high-priority messages first
public class PriorAuthConsumer : IConsumer<ProcessPriorAuthCommand>
{
    public async Task Consume(ConsumeContext<ProcessPriorAuthCommand> context)
    {
        var command = context.Message;
        var priority = context.Priority;

        _logger.LogInformation("Processing prior auth {RequestId} with priority {Priority}",
            command.RequestId, priority);

        if (command.IsUrgent)
        {
            // Expedited clinical review
            await _reviewService.ExpediteReviewAsync(command);
        }
        else
        {
            // Standard review queue
            await _reviewService.QueueForReviewAsync(command);
        }
    }
}
```

**Configuration** (RabbitMQ):
```json
{
  "QueueName": "priorauth.requests",
  "Durable": true,
  "Arguments": {
    "x-max-priority": 10
  }
}
```

**Use Cases**: STAT medication orders, emergency procedures, high-value claims, VIP members

