[patterns/application/api-microservices/PTN-APP-API-030-message-queue-pattern.md#variation-3-request-reply-with-correlation]

#### Variation 3: Request-Reply with Correlation

**Scenario**: Async request-response for long-running operations (prior auth, credentialing)

**Implementation**:

```csharp
// Request: Submit prior auth for review
public async Task<string> RequestPriorAuthorizationAsync(PriorAuthRequest request)
{
    var correlationId = Guid.NewGuid().ToString();

    await _bus.Publish(new PriorAuthRequestCommand
    {
        RequestId = request.Id,
        CorrelationId = correlationId,
        MemberId = request.MemberId,
        ServiceCode = request.ServiceCode,
        ClinicalJustification = request.Justification
    });

    // Store correlation for matching reply
    await _correlationStore.SaveAsync(new Correlation
    {
        CorrelationId = correlationId,
        RequestId = request.Id,
        RequestedAt = DateTime.UtcNow,
        ExpiresAt = DateTime.UtcNow.AddDays(7)
    });

    return correlationId; // Return to caller for tracking
}

// Reply: Clinical reviewer approves/denies
public async Task PublishPriorAuthDecisionAsync(string correlationId, PriorAuthDecision decision)
{
    await _bus.Publish(new PriorAuthDecisionEvent
    {
        CorrelationId = correlationId,
        IsApproved = decision.IsApproved,
        DenialReason = decision.DenialReason,
        ApprovedUnits = decision.ApprovedUnits,
        ValidThrough = decision.ValidThrough,
        ReviewedBy = decision.ReviewerId,
        ReviewedAt = DateTime.UtcNow
    });
}

// Consumer matches reply to original request
public class PriorAuthDecisionConsumer : IConsumer<PriorAuthDecisionEvent>
{
    public async Task Consume(ConsumeContext<PriorAuthDecisionEvent> context)
    {
        var decision = context.Message;

        // Find original request using correlation ID
        var correlation = await _correlationStore.GetByCorrelationIdAsync(decision.CorrelationId);

        if (correlation == null)
        {
            _logger.LogWarning("Received orphaned decision for correlation {CorrelationId}",
                decision.CorrelationId);
            return;
        }

        // Update prior auth record
        await _priorAuthService.RecordDecisionAsync(correlation.RequestId, decision);

        // Notify provider
        await _notificationService.NotifyProviderAsync(correlation.RequestId, decision);

        // Clean up correlation
        await _correlationStore.DeleteAsync(decision.CorrelationId);
    }
}
```

**Benefits**: Non-blocking request-response; supports long-running processes (hours/days); handles timeouts gracefully

