#### Variation 4: Batch Processing with Aggregation

**Scenario**: Accumulate messages and process in batches for efficiency (nightly files, bulk notifications)

**Implementation**:

```csharp
// Consumer aggregates messages into batches
public class EligibilityFileConsumer : IConsumer<EligibilityUpdateEvent>
{
    private readonly List<EligibilityUpdateEvent> _batch = new();
    private readonly SemaphoreSlim _batchLock = new(1);
    private readonly Timer _batchTimer;

    public EligibilityFileConsumer()
    {
        // Process batch every 5 minutes or when reaching 10,000 records
        _batchTimer = new Timer(ProcessBatchCallback, null, TimeSpan.FromMinutes(5), TimeSpan.FromMinutes(5));
    }

    public async Task Consume(ConsumeContext<EligibilityUpdateEvent> context)
    {
        await _batchLock.WaitAsync();
        try
        {
            _batch.Add(context.Message);

            if (_batch.Count >= 10000)
            {
                await ProcessBatchAsync();
            }
        }
        finally
        {
            _batchLock.Release();
        }
    }

    private async Task ProcessBatchAsync()
    {
        if (!_batch.Any()) return;

        var batchCopy = new List<EligibilityUpdateEvent>(_batch);
        _batch.Clear();

        // Generate file
        var fileName = $"eligibility_{DateTime.UtcNow:yyyyMMddHHmmss}.dat";
        await _fileGenerator.GenerateEligibilityFileAsync(fileName, batchCopy);

        // Upload to SFTP
        await _sftpClient.UploadAsync(fileName, "state-mmis");

        _logger.LogInformation("Processed batch of {Count} eligibility updates", batchCopy.Count);
    }
}
```

**Use Cases**: State reporting files, bulk notifications, financial reconciliation, data warehouse loads

