**Step 2: Configure First Queue and Exchange**

```csharp
// Define queue topology using MassTransit
public class ClaimProcessingQueueConfiguration : IConfigurationSection
{
    public void Configure(IRabbitMqBusFactoryConfigurator configurator)
    {
        // Define exchange
        configurator.Message<ProcessClaimCommand>(x =>
        {
            x.SetEntityName("claims.processing.exchange");
        });

        // Configure queue
        configurator.ReceiveEndpoint("claims.processing.queue", e =>
        {
            e.Durable = true;
            e.AutoDelete = false;
            e.PrefetchCount = 10;

            // Dead letter configuration
            e.Bind("claims.processing.exchange", b =>
            {
                b.ExchangeType = ExchangeType.Direct;
            });

            e.Arguments.Add("x-dead-letter-exchange", "claims.dlq.exchange");
            e.Arguments.Add("x-dead-letter-routing-key", "claims.failed");
            e.Arguments.Add("x-message-ttl", 86400000); // 24 hours

            e.ConfigureConsumer<ClaimProcessingConsumer>(context);
        });

        // Configure Dead Letter Queue
        configurator.ReceiveEndpoint("claims.dlq.queue", e =>
        {
            e.Durable = true;
            e.AutoDelete = false;

            // Manual inspection only - no automatic consumption
        });
    }
}
```

**Step 3: Implement First Producer**

```csharp
public class ClaimSubmissionService
{
    private readonly IBus _bus;
    private readonly ILogger<ClaimSubmissionService> _logger;

    public async Task SubmitClaimAsync(Claim claim)
    {
        // Validate claim before publishing
        var validationResult = await _validator.ValidateAsync(claim);
        if (!validationResult.IsValid)
        {
            throw new ValidationException(validationResult.Errors);
        }

        // Publish message with metadata
        await _bus.Publish(new ProcessClaimCommand
        {
            ClaimId = claim.Id,
            MemberId = claim.MemberId,
            ProviderId = claim.ProviderId,
            ServiceDate = claim.ServiceDate,
            TotalAmount = claim.TotalAmount,
            LineItems = claim.LineItems.Select(li => new ClaimLineItem
            {
                ServiceCode = li.ServiceCode,
                Quantity = li.Quantity,
                UnitPrice = li.UnitPrice
            }).ToList()
        }, ctx =>
        {
            // Add correlation ID for tracing
            ctx.CorrelationId = claim.CorrelationId ?? Guid.NewGuid();

            // Set message properties
            ctx.TimeToLive = TimeSpan.FromHours(24);
            ctx.Headers.Set("SubmittedBy", claim.SubmittedBy);
            ctx.Headers.Set("StateProgram", claim.StateProgramId);
        });

        _logger.LogInformation(
            "Claim {ClaimId} published for processing with correlation {CorrelationId}",
            claim.Id, ctx.CorrelationId);
    }
}
```

**Step 4: Implement First Consumer with Error Handling**

```csharp
public class ClaimProcessingConsumer : IConsumer<ProcessClaimCommand>
{
    private readonly IClaimAdjudicationEngine _adjudicationEngine;
    private readonly IClaimRepository _claimRepository;
    private readonly ILogger<ClaimProcessingConsumer> _logger;

    public async Task Consume(ConsumeContext<ProcessClaimCommand> context)
    {
        var command = context.Message;

        using var scope = _logger.BeginScope(new Dictionary<string, object>
        {
            ["ClaimId"] = command.ClaimId,
            ["CorrelationId"] = context.CorrelationId
        });

        _logger.LogInformation("Processing claim {ClaimId}", command.ClaimId);

        try
        {
            // Idempotency check
            var existing = await _claimRepository.GetByIdAsync(command.ClaimId);
            if (existing?.Status == ClaimStatus.Processed)
            {
                _logger.LogInformation("Claim {ClaimId} already processed - skipping", command.ClaimId);
                return; // ACK message without reprocessing
            }

            // Perform adjudication
            var result = await _adjudicationEngine.AdjudicateAsync(command);

            // Save result
            await _claimRepository.SaveAdjudicationResultAsync(command.ClaimId, result);

            // Publish completion event
            await context.Publish(new ClaimAdjudicatedEvent
            {
                ClaimId = command.ClaimId,
                ApprovedAmount = result.ApprovedAmount,
                DenialReason = result.DenialReason,
                AdjudicatedAt = DateTime.UtcNow
            });

            _logger.LogInformation("Claim {ClaimId} successfully adjudicated", command.ClaimId);
        }
        catch (TransientException ex) when (IsRetryable(ex))
        {
            // Transient failure - requeue for automatic retry
            _logger.LogWarning(ex, "Transient failure processing claim {ClaimId} - will retry", command.ClaimId);
            throw; // Framework handles retry with exponential backoff
        }
        catch (ValidationException ex)
        {
            // Invalid data - move to DLQ
            _logger.LogError(ex, "Validation failure for claim {ClaimId}", command.ClaimId);

            await context.Publish(new ClaimValidationFailedEvent
            {
                ClaimId = command.ClaimId,
                ValidationErrors = ex.Errors,
                FailedAt = DateTime.UtcNow
            });

            // NACK without requeue - moves to DLQ
            throw new MessageNotConsumedException(ex.Message);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Unexpected error processing claim {ClaimId}", command.ClaimId);
            throw; // Will retry, then move to DLQ after max attempts
        }
    }

    private bool IsRetryable(Exception ex)
    {
        return ex is TimeoutException
            || ex is HttpRequestException
            || ex is SqlException { Number: 1205 }; // SQL deadlock
    }
}
```

