```csharp
public class DeadLetterQueueMonitor : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            // Check DLQ periodically
            var dlqMessages = await _queueInspector.GetDeadLetterMessagesAsync("claims.dlq.queue");

            foreach (var message in dlqMessages)
            {
                // Log for investigation
                _logger.LogWarning(
                    "Message {MessageId} in DLQ: {Reason}",
                    message.MessageId, message.FailureReason);

                // Classify failure type
                var classification = ClassifyFailure(message);

                switch (classification)
                {
                    case FailureType.PoisonMessage:
                        // Move to poison message store for manual review
                        await _poisonMessageStore.StoreAsync(message);
                        await _queueInspector.DeleteMessageAsync(message.MessageId);
                        break;

                    case FailureType.ServiceDown:
                        // Service recovered - attempt replay
                        if (await IsServiceHealthyAsync(message.TargetService))
                        {
                            await _queueInspector.ReplayMessageAsync(message.MessageId);
                        }
                        break;

                    case FailureType.DataIssue:
                        // Create support ticket for data correction
                        await _ticketingService.CreateTicketAsync(
                            $"DLQ Message {message.MessageId}",
                            message.FailureReason,
                            message.Payload);
                        break;
                }
            }

            await Task.Delay(TimeSpan.FromMinutes(5), stoppingToken);
        }
    }
}
