public class MessageEncryptionFilter : IFilter<PublishContext>
{
    private readonly IDataProtector _protector;

    public async Task Send(PublishContext context, IPipe<PublishContext> next)
    {
        if (context.Message is IContainsPHI phiMessage)
        {
            // Encrypt sensitive fields
            phiMessage.MemberId = _protector.Protect(phiMessage.MemberId);
            phiMessage.MemberName = _protector.Protect(phiMessage.MemberName);
            phiMessage.SSN = _protector.Protect(phiMessage.SSN);

            // Add encryption marker
            context.Headers.Set("X-Encrypted", "true");
            context.Headers.Set("X-Encryption-Algorithm", "AES256-GCM");
        }

        await next.Send(context);
    }
}

public class MessageDecryptionFilter : IFilter<ConsumeContext>
{
    public async Task Send(ConsumeContext context, IPipe<ConsumeContext> next)
    {
        if (context.Headers.TryGetHeader("X-Encrypted", out var encrypted) &&
            encrypted.ToString() == "true")
        {
            if (context.Message is IContainsPHI phiMessage)
            {
                // Decrypt sensitive fields
                phiMessage.MemberId = _protector.Unprotect(phiMessage.MemberId);
                phiMessage.MemberName = _protector.Unprotect(phiMessage.MemberName);
                phiMessage.SSN = _protector.Unprotect(phiMessage.SSN);
            }
        }

        await next.Send(context);
    }
}
