public async Task<AdjudicationResponse> AdjudicateRxClaimAsync(PharmacyClaim claim)
{
    // Step 1: Quick eligibility and formulary checks (synchronous)
    var eligibility = await _eligibilityCache.GetAsync(claim.MemberId);
    if (!eligibility.IsActive)
        return AdjudicationResponse.Reject("Member not eligible");

    var formulary = await _formul aryCache.CheckAsync(claim.DrugNdc);
    if (!formulary.IsCovered)
        return AdjudicationResponse.Reject("Drug not covered");

    // Step 2: Approve claim provisionally
    var provisionalApproval = new AdjudicationResponse
    {
        Status = "Approved",
        ApprovedAmount = formulary.CopayAmount,
        ClaimId = claim.Id
    };

    // Step 3: Queue for async DUR review (doesn't block pharmacy)
    await _bus.Publish(new ReviewPharmacyClaimCommand
    {
        ClaimId = claim.Id,
        MemberId = claim.MemberId,
        DrugNdc = claim.DrugNdc,
        Quantity = claim.Quantity,
        PrescriberNpi = claim.PrescriberNpi
    });

    // Return to pharmacy immediately (<1 second)
    return provisionalApproval;
}

// Async DUR review consumer
public class DrugUtilizationReviewConsumer : IConsumer<ReviewPharmacyClaimCommand>
{
    public async Task Consume(ConsumeContext<ReviewPharmacyClaimCommand> context)
    {
        var cmd = context.Message;

        try
        {
            // Comprehensive DUR analysis (may take 5-10 seconds)
            var durResult = await _durService.PerformUtilizationReviewAsync(cmd);

            if (durResult.HasConcerns)
            {
                // Retroactive reversal if serious drug interaction found
                await _claimService.ReverseClaimAsync(cmd.ClaimId, durResult.Reason);
                await _notificationService.AlertPharmacyAsync(cmd.ClaimId, durResult);
                await _notificationService.AlertPrescriberAsync(cmd.PrescriberNpi, durResult);
            }

            // Log DUR completion
            await _durRepository.SaveReviewAsync(cmd.ClaimId, durResult);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "DUR review failed for claim {ClaimId}", cmd.ClaimId);
            // Message will retry automatically; claim already approved at pharmacy
        }
    }
}
```

